  await page.getByRole('button',{name:'Open navigation',exact:true}).click();await page.getByRole('button',{name:'Cash',exact:true}).filter({visible:true}).click();await expect(page.getByRole('combobox',{name:'Account',exact:true})).toHaveValue('C-account');
  await context.setOffline(true);await chooseLanguage(page,'ไทย');await expect.poll(async()=>(await repo(page,'pending')).filter((r:any)=>r.value.command.operation==='preference.update').length).toBe(1);const queued=(await repo(page,'pending'))[0].value.command;expect(queued.inputs).toEqual({language:'ไทย',statementAccountId:'C-account',statementDate:'2026-10-09'});expect(writes).toEqual([]);/* The waiting-to-sync note follows the language chosen after it was set (preference-save keeps both languages). */const prefNote=page.locator('p[role=status]');await expect(prefNote.filter({hasText:'บันทึกบนอุปกรณ์แล้ว รอซิงค์'})).not.toHaveCount(0);await expect(prefNote.filter({hasText:'Saved on this device. Waiting to sync.'})).toHaveCount(0);
  await page.reload();await expect(page.locator('.live-body')).toBeVisible();await expect(page.locator('html')).toHaveAttribute('lang','th');expect((await repo(page,'pending'))[0].value.command).toEqual(queued);await page.getByRole('button',{name:'เปิดเมนู',exact:true}).click();await expect(page.getByRole('button',{name:'EN',exact:true}).filter({visible:true})).toBeDisabled();await page.getByRole('button',{name:'ปิดเมนู',exact:true}).click();
  await context.setOffline(false);await page.evaluate(()=>window.dispatchEvent(new Event('online')));await expect.poll(()=>writes.length).toBe(1);expect(writes[0]).toEqual(queued);await expect.poll(async()=>(await repo(page,'pending')).length).toBe(0);await expect(page.locator('html')).toHaveAttribute('lang','th');
