test('Native workspace transition keeps fixed chrome opaque above moving content and supports immediate fallbacks',async({},info)=>{
 const{context,page}=await launch();try{
 await page.setViewportSize({width:390,height:844});await page.emulateMedia({reducedMotion:'no-preference'});await page.waitForTimeout(450);
 await page.addStyleTag({content:'.live-shell main{min-height:1800px}'});
 await page.evaluate(()=>{const d=document as any;const original=d.startViewTransition.bind(d);(window as any).__nativeTransition=original;(window as any).__transitionCaptures=[];d.startViewTransition=(callback:any)=>{const transition=original(callback);transition.ready.then(()=>{const animations=document.getAnimations().filter((a:any)=>a.effect?.pseudoElement?.includes('view-transition'));for(const animation of animations){animation.pause();animation.currentTime=75}(window as any).__transitionCaptures.push(animations.map((a:any)=>({pseudo:a.effect.pseudoElement,time:a.currentTime,state:a.playState})));(window as any).__heldTransition=transition});return transition}});
 const chrome=async()=>page.locator('.topbar,.live-bottom-nav').evaluateAll((nodes:Element[])=>nodes.map(node=>{const r=node.getBoundingClientRect();return{x:r.x,y:r.y,width:r.width,height:r.height}}));
 for(const [index,destination] of ['Dashboard','Borrowers'].entries()){
 if(index===1)await page.evaluate(()=>window.scrollTo(0,300));const before=await chrome();await page.locator('.live-bottom-nav').getByRole('button',{name:destination,exact:true}).click();await expect.poll(()=>page.evaluate(()=>(window as any).__transitionCaptures.length)).toBe(index+1);
 const state=await page.evaluate(()=>{const css=(p:string)=>{const s=getComputedStyle(document.documentElement,p);return{z:s.zIndex,opacity:s.opacity,animation:s.animationName,blend:s.mixBlendMode,transform:s.transform}};return{captures:(window as any).__transitionCaptures.at(-1),footer:css('::view-transition-new(live-footer)'),header:css('::view-transition-new(live-header)'),footerGroup:css('::view-transition-group(live-footer)'),workspaceGroup:css('::view-transition-group(workspace)'),workspace:css('::view-transition-new(workspace)')}});
 expect(state.captures.some((a:any)=>a.pseudo==='::view-transition-new(workspace)'&&a.time===75&&a.state==='paused')).toBe(true);expect(state.workspace.transform).not.toBe('none');for(const item of [state.footer,state.header]){expect(item.opacity).toBe('1');expect(item.animation).toBe('none');expect(item.blend).toBe('normal')}expect(Number(state.footerGroup.z)).toBeGreaterThan(Number(state.workspaceGroup.z));expect(await chrome()).toEqual(before);await expect(page.locator('.live-bottom-nav button svg.app-icon')).toHaveCount(4);await expect(page.locator('.live-bottom-nav').getByRole('button',{name:destination,exact:true})).toHaveAttribute('aria-current','page');await page.screenshot({path:info.outputPath('native-transition-'+index+'-390.png')});await page.evaluate(async()=>{for(const animation of document.getAnimations())animation.finish();await(window as any).__heldTransition.finished});
 }
 await page.setViewportSize({width:1440,height:900});const sidebarBefore=await page.locator('.live-desktop-nav').boundingBox();await page.locator('#live-desktop-navigation').getByRole('button',{name:'Dashboard',exact:true}).click();await expect.poll(()=>page.evaluate(()=>(window as any).__transitionCaptures.length)).toBe(3);expect(await page.locator('.live-desktop-nav').boundingBox()).toEqual(sidebarBefore);expect(await page.evaluate(()=>getComputedStyle(document.documentElement,'::view-transition-new(live-sidebar)').opacity)).toBe('1');await page.evaluate(async()=>{for(const animation of document.getAnimations())animation.finish();await(window as any).__heldTransition.finished});
 await page.emulateMedia({reducedMotion:'reduce'});await page.locator('#live-desktop-navigation').getByRole('button',{name:'Borrowers',exact:true}).click();await expect(page.locator('main[data-workspace="borrowers"]')).toBeVisible();expect(await page.evaluate(()=>(window as any).__transitionCaptures.length)).toBe(3);
 await page.emulateMedia({reducedMotion:'no-preference'});await page.evaluate(()=>{(document as any).startViewTransition=undefined});await page.locator('#live-desktop-navigation').getByRole('button',{name:'Dashboard',exact:true}).click();await expect(page.locator('main[data-workspace="dashboard"]')).toBeVisible();expect(await page.evaluate(()=>(window as any).__transitionCaptures.length)).toBe(3);
 }finally{await context.close()}
});

