 await page.setViewportSize({width:390,height:844});await page.waitForTimeout(450);await page.evaluate(()=>{(window as any).__pullEvents=[];Object.defineProperty(navigator,'vibrate',{configurable:true,value:(duration:number)=>{(window as any).__pullEvents.push('vibrate:'+duration);return true}});document.querySelector('.collection-update')!.addEventListener('click',()=>{(window as any).__pullEvents.push('refresh')})});
