async function installSyntheticWaitingWorker(page:Page,fail=false){await page.evaluate(fail=>{const registration=(window as any).__pwaRegistration;if(!registration)throw Error('Captured registration missing');const worker=new EventTarget() as any;worker.state='installed';worker.postMessage=(message:any,ports:any[])=>{if(message.type==='GET_BUILD_VERSION'){void fetch('/build-version.json').then(r=>r.json()).then(value=>ports[0].postMessage({version:value.version}));return}if(message.type==='ACTIVATE_UPDATE'){(window as any).__activationMessages=((window as any).__activationMessages??0)+1;if(fail)throw Error('Synthetic activation failure')}};(window as any).__waitingWorker=worker;Object.defineProperty(registration,'waiting',{configurable:true,get:()=>worker});Object.defineProperty(registration,'installing',{configurable:true,get:()=>worker});registration.dispatchEvent(new Event('updatefound'));worker.dispatchEvent(new Event('statechange'));},fail)}
async function controllerChanged(page:Page){await page.evaluate(()=>{Object.defineProperty(navigator.serviceWorker,'controller',{configurable:true,get:()=>(window as any).__waitingWorker});navigator.serviceWorker.dispatchEvent(new Event('controllerchange'))})}
